public LogDao(String connectionString, String user, String password, String dbName, MeterRegistry meterRegistry) {
    if (StringUtils.isEmpty(dbName)) {
        dbName = DEFAULT_DB_NAME;
    }
    verifyDBName(dbName);
    if (StringUtils.isEmpty(connectionString)) {
        this.dbConnection = null;
        this.dbName = dbName;
        bypassLog = true;
    } else {
        this.dbConnection = new DBConnection(connectionString, user, password);
        this.dbName = dbName;
        createDatabase();
        createApplicationSubmissionTable();
        createLogIndexTable();
    }
    failureMetrics = new CounterMetricContainer(meterRegistry);
    timerMetrics = new TimerMetricContainer(meterRegistry);
}
